-- =========================================================
-- FarmTablet v2 – Constants
-- Single source of truth for the entire design system
-- =========================================================
FT = FT or {}

FT.VERSION = "2.5.3.0"   -- keep in sync with modDesc.xml <version>; shown in the tablet UI

-- Generic localization helpers.  This keeps old app scripts from drawing
-- fixed English labels directly on screen: if a visible text has a matching
-- translation key, the renderer swaps it before drawing.
function FT.l10n(key, fallback)
    if g_i18n ~= nil and key ~= nil and g_i18n.hasText ~= nil and g_i18n:hasText(key) then
        local text = g_i18n:getText(key)
        if text ~= nil and text ~= "" then return text end
    end
    return fallback or tostring(key or "")
end

function FT.l10nFormat(key, fallback, ...)
    local text = FT.l10n(key, fallback)
    local ok, result = pcall(string.format, text, ...)
    if ok then return result end
    return text
end

function FT.l10nAuto(text)
    if text == nil then return "" end
    local raw = tostring(text)
    if raw == "" then return raw end

    -- 1) exact text -> l10n key mapping
    if FT.AUTO_L10N ~= nil then
        local key = FT.AUTO_L10N[raw]
        if key ~= nil then return FT.l10n(key, raw) end
    end

    -- 2) dynamic UI strings assembled by scripts (e.g. "Autumn  -  Day 6",
    --    "FOOD  80%", "Cows (12 / 20)", "4 pens").  These would never
    --    match an exact key, so translate the visible words before drawing.
    local function tr(word)
        if word == nil or word == "" then return word end
        if FT.AUTO_L10N ~= nil then
            local k = FT.AUTO_L10N[word] or FT.AUTO_L10N[string.upper(word)] or FT.AUTO_L10N[string.lower(word)]
            if k ~= nil then return FT.l10n(k, word) end
        end
        return word
    end

    -- Season/date line on the lock screen: "Autumn  -  Day 6"
    local season, day = raw:match("^(%a+)%s*%-%s*Day%s+(%d+)$")
    if season and day then
        return string.format(FT.l10n("ft_lockscreen_date_day", "%s  -  Day %d"), tr(season), tonumber(day) or day)
    end

    -- Simple count labels: "4 pens", "1 vehicle", "3 jobs", "2 fields"
    local n, unit = raw:match("^(%d+)%s+([A-Za-z]+)$")
    if n and unit then
        local keySing = "ft_count_" .. string.lower(unit:gsub("s$", ""))
        local keyPlur = keySing .. "s"
        local num = tonumber(n) or 0
        if num == 1 then return string.format(FT.l10n(keySing, "%d " .. unit), num) end
        return string.format(FT.l10n(keyPlur, "%d " .. unit), num)
    end

    -- Metric lines: "FOOD  80%", "WATER  25%", "STRAW/CLEAN  90%"
    local label, pct = raw:match("^([A-Z/ ]+)%s+(%d+%%)$")
    if label and pct then
        label = label:gsub("%s+$", "")
        return tr(label) .. "  " .. pct
    end

    -- Animal/crop headers with count suffix: "Cows  (12 / 20)" or "COW (12 / 20)"
    local first, rest = raw:match("^([A-Za-z_]+)%s*(%b())$")
    if first and rest then
        return tr(first) .. "  " .. rest
    end

    -- Common prefix/suffix variants: "Day 6", "Started Day 3 at 08:00"
    local d = raw:match("^Day%s+(%d+)$")
    if d then return string.format(FT.l10n("ft_dynamic_day", "Day %d"), tonumber(d) or d) end
    local sd, at = raw:match("^Started Day%s+(%d+)%s+at%s+(.+)$")
    if sd and at then return string.format(FT.l10n("ft_dynamic_started_day_at", "Started Day %d at %s"), tonumber(sd) or sd, at) end

    -- 3) common composed labels that include values/options and therefore do
    --    not match exact keys.  Keep this renderer-side so old app code stays
    --    dedi-save and gameplay logic is untouched.
    local function trim(v) return tostring(v or ""):gsub("^%s+", ""):gsub("%s+$", "") end

    local before, after = raw:match("^([^:]+):%s*(.+)$")
    if before and after then
        return tr(trim(before)) .. ": " .. tr(trim(after))
    end

    local left, right = raw:match("^(.+)%s+·%s+(.+)$")
    if left and right then
        local rNum, rWord = right:match("^(%d+)%s+([A-Za-z]+)$")
        if rNum and rWord then
            right = FT.l10nAuto(rNum .. " " .. rWord)
        else
            local k, v = right:match("^([A-Za-z ]+):%s*(.+)$")
            if k and v then right = tr(trim(k)) .. ": " .. v else right = tr(trim(right)) end
        end
        return tr(trim(left)) .. "  ·  " .. right
    end

    -- Uppercase/simple labels such as "DEEP SPACE", "ENTER EDIT MODE",
    -- "TIME SCALE", "ALL REPAIR".  Translate exact phrase first; if only
    -- single words are known, translate word by word.
    if raw:match("^[A-Z0-9%+%-%s_/&%.]+$") then
        local exact = tr(trim(raw))
        if exact ~= raw then return exact end
        local changed = false
        local out = raw:gsub("[A-Z][A-Z0-9_]*", function(w)
            local tw = tr(w)
            if tw ~= w then changed = true end
            return tw
        end)
        if changed then return out end
    end

    return raw
end

