    -- Content (right of sidebar)
    contentX = 0, contentY = 0, contentW = 0, contentH = 0,
    -- Topbar
    topbarX = 0, topbarY = 0, topbarW = 0, topbarH = 0,
    -- Scale factors
    scaleX = 1, scaleY = 1,
    -- Text scale: tabletScale * contentFontScale. Applied to every rendered
