    ["ft_fields_col_crop"] = "FRUCHT",
    ["ft_fields_col_state"] = "STATUS",
    ["ft_fields_count"] = "%d Felder",
    ["ft_fields_help_columns_body"] = "# = Feld-ID. FRUCHT = Fruchtart. HA = Feldfläche in Hektar. STATUS = aktueller Feldzustand.",
    ["ft_fields_help_columns_title"] = "SPALTEN: # / FRUCHT / HA / STATUS",
    ["ft_fields_help_scrolling_body"] = "Wenn du mehr Felder besitzt, als auf den Bildschirm passen, kann die Liste mit dem Mausrad gescrollt werden.",
    ["ft_fields_help_scrolling_title"] = "SCROLLEN",
    ["ft_fields_help_state_colors_body"] = "Grün  = bereit zur Ernte. Blau   = wächst normal. Gelb   = benötigt Aufmerksamkeit, z.B. düngen, pflügen oder walzen. Grau   = leer / unbestelltes Feld.",
    ["ft_fields_help_state_colors_title"] = "STATUS-FARBEN",
    ["ft_fields_help_summary_body"] = "Oben werden die Summen angezeigt: BEREIT für Felder, die geerntet werden können, WÄCHST für wachsende Kulturen und LEER für Felder ohne aktive Frucht.",
    ["ft_fields_help_summary_title"] = "ÜBERSICHT",
    ["ft_fields_none"] = "Du besitzt noch keine Felder.",
    ["ft_fields_none_hint"] = "Kaufe Land, um mit dem Farmen zu beginnen.",
    ["ft_fws_factories"] = "FABRIKEN",
    ["ft_fws_factories_open"] = "Fabriken offen",
    ["ft_fws_factory"] = "Fabrik",
    ["ft_fws_fire_system"] = "Feuer-System",
    ["ft_fws_no_event"] = "Kein Ereignis",
    ["ft_fws_no_factories"] = "Noch keine Fabriken im FactoryWeekSchedule-HUD-Cache.",
    ["ft_fws_not_detected"] = "FactoryWeekSchedule wurde nicht erkannt.",
    ["ft_fws_open_count"] = "%d/%d offen",
    ["ft_help_a1_dash_text"] = "Das Dashboard ist Ihre Farmzusammenfassung auf einen Blick. Oben wird Ihr aktuelles Guthaben auf einer großen Heldenkarte angezeigt, darunter Einnahmen, Ausgaben und Nettogewinn für die Sitzung. Farm Stats listet auf, wie viele Felder Sie besitzen und wie viele Fahrzeuge Sie insgesamt haben. Im Abschnitt „Welt“ werden die aktuelle Jahreszeit, der aktuelle Tag und die aktuelle Tageszeit sowie ein Live-Wetter-Schnappschuss angezeigt. Tippen Sie auf das kleine Infosymbol in der unteren rechten Ecke des Dashboards, um eine detaillierte Erklärung jedes Werts zu erhalten.",
    ["ft_help_a1_dash_title"] = "Armaturenbrett",
    ["ft_help_a1_title"] = "Dashboard und Wetter",
    ["ft_help_a1_weather_text"] = "Die Wetter-App zeigt eine detaillierte mehrtägige Vorhersage mit Temperatur, Niederschlagswahrscheinlichkeit und Wind. Die Bedingungen sind farblich gekennzeichnet: Blau für Regen, Orange für Stürme, Weiß für klaren Himmel. Verwenden Sie dies zusammen mit dem Crop Stress-Mod, um zu entscheiden, wann die Bewässerung geplant werden soll.",
    ["ft_help_a1_weather_title"] = "Wetter-App",
    ["ft_help_a2_animals_text"] = "Die Tiers-App zeigt jeden Stall, den Sie besitzen, mit drei Fortschrittsbalken an: Futterstand, Wasserstund und Sauberkeit. Grüne Balken erfordern keine Maßnahmen. Gelbe Balken sollten bald aufgefüllt werden. Rote Balken sind kritisch und beeinträchtigen die Produktivität, wenn sie unbeaufsichtigt bleiben.",
    ["ft_help_a2_animals_title"] = "Tiere",
    ["ft_help_a2_fields_text"] = "Field Manager listet alle Felder auf, die Sie besitzen. In jeder Zeile werden die Pflanzenart, die aktuelle Wachstumsphase als Abzeichen (Aussaat, Wachsend, Bereit) und ein farbcodierter Statuspunkt angezeigt. Grün bedeutet, dass das Feld keine Aufmerksamkeit benötigt. Gelb bedeutet, dass etwas benötigt wird – Dünger, Pflügen oder Walzen. Rot bedeutet, dass die Ernte zur Ernte bereit ist oder dringende Maßnahmen erforderlich sind.",
    ["ft_help_a2_fields_title"] = "Feldmanager",
    ["ft_help_a2_title"] = "Felder & Tiere",
    ["ft_help_a3_bucket_text"] = "Bucket Tracker wird automatisch aktiviert, wenn Sie einen Radlader, Bagger oder Materialumschlaggerät fahren. Es zählt jeden Entladezyklus und führt ein fortlaufendes Protokoll über die Materialart und das geschätzte Gewicht pro Ladung. Verwenden Sie es, um die Produktivität bei Erdarbeiten, Gülleausbringung oder Schüttguttransportarbeiten zu verfolgen.",
    ["ft_help_a3_bucket_title"] = "Eimer-Tracker",
    ["ft_help_a3_title"] = "Werkstatt- und Bucket-Tracker",
    ["ft_help_a3_workshop_text"] = "Gehen Sie weniger als 35 Meter ein ein beliebiges Fahrzeug herein und es wird automatisch in der Workshop-App angezeigt. Jeder Eintrag zeigt den Kraftstoffstand, den Verschleißprozentsatz und die Gesamtbetriebsstunden an. Klicken Sie bei einem beliebigen Fahrzeug auf „AUSWÄHLEN“, um es anzupinnen – angeheftete Fahrzeuge bleiben in der App sichtBalken, auch wenn Sie weggehen, sodass Sie die auf dem Feld arbeitenden Maschinen ganz einfach überwachen können.",
    ["ft_help_a3_workshop_title"] = "Werkstatt",
    ["ft_help_cat_apps"] = "Farm-Apps",
    ["ft_help_cat_mods"] = "Companion-Mods",
    ["ft_help_cat_settings"] = "Einstellungen und Konsole",
    ["ft_help_cat_start"] = "Erste Schritte",
    ["ft_help_m1_income_text"] = "Wenn FS25_IncomeMod aktiv ist, erscheint die Einkommen-App auf dem Startbildschirm. Sie zeigt Zahlungsmodus und Betrag und erlaubt das Ein- oder Ausschalten des Mods, ohne das Tablet zu verlassen. Aenderungen wirken sofort.",
    ["ft_help_m1_income_title"] = "FS25 Einkommensmod",
    ["ft_help_m1_tax_text"] = "Wenn FS25_TaxMod aktiv ist, zeigt die Steuer-App Ihren aktuellen Steuersatz, den Renditeprozentsatz und die in dieser Sitzung insgesamt gezahlten Steuern an. Sie können den Mod über das Tablet ein- oder ausschalten und sehen auf einen Blick, wie viel Mindestguthaben Sie benötigen.",
    ["ft_help_m1_tax_title"] = "FS25 Steuermod",
    ["ft_help_m1_title"] = "Einkommens- und Steuermodifikationen",
    ["ft_help_m2_cropstress_text"] = "Wenn FS25_SeasonalCropStress aktiv ist, listet die Crop Stress-App jedes Feld mit seinem aktuellen Bodenfeuchtigkeitsprozentsatz und dem akkumulierten Trockenstress auf. Ein farbcodierter Balken zeigt den Gesundheitszustund auf einen Blick an: Grün ist in Ordnung, Gelb ist eine Warnung, Rot bedeutet, dass sich bereits Stress aufbaut und der Ertragsverlust begonnen hat. Installieren Sie diesen Mod und öffnen Sie einen eigenen Hilfebereich für eine vollständige Anleitung zur Bewässerung.",
    ["ft_help_m2_cropstress_title"] = "FS25 Saisonaler Pflanzenstress",
    ["ft_help_m2_soil_text"] = "Wenn FS25_SoilFertilizer aktiv ist, zeigt die Soil Fertilizer-App Stickstoff, Phosphor, Kalium, pH-Wert und organische Substanz pro Feld an. Wählen Sie ein beliebiges Feld aus der Liste aus, um dessen vollständiges Bodenprofil anzuzeigen und festzustellen, ob es gedüngt werden muss. Der Nährstoffgehalt ist farblich gekennzeichnet: Grün ist gut, Gelb ist mittelmäßig, Rot erfordert Aufmerksamkeit.",
    ["ft_help_m2_soil_title"] = "FS25 Bodendünger",
    ["ft_help_m2_title"] = "Pflanzenstress und Bodendünger",
    ["ft_help_m3_appstore_text"] = "Die App Store-App listet alle auf dem Tablet registrierten Apps auf, einschließlich Companion-Mod-Apps. Apps, die einen Mod erfordern, der derzeit nicht aktiv ist, werden abgeblendet angezeigt, sodass Sie wissen, dass sie verfügBalken sind, sobald Sie den passenden Mod aktivieren. Es ist keine Konfiguration erforderlich – Begleit-Apps werden automatisch angezeigt, wenn ihr Mod geladen wird.",
    ["ft_help_m3_appstore_title"] = "Erkennen installierter Apps",
    ["ft_help_m3_title"] = "App Store",
    ["ft_help_p1_nav_text"] = "Das Farm-Tablet funktioniert wie ein Smartphone. Zum Entsperren wischen, danach auf dem Startbildschirm ein App-Symbol antippen, um es zu oeffnen. Tippe oben auf HOME, um zum Raster zurueckzukehren. Das Dock am unteren Rund enthaelt deine Favoriten, mit dem Mausrad wechselst du die Seiten. Die App-Store-App zeigt alle vorhandenen Apps.",
    ["ft_help_p1_nav_title"] = "Startbildschirm & Apps",
    ["ft_help_p1_open_text"] = "Drücken Sie jederzeit T (konfigurierBalken), um das Farm Tablet zu öffnen oder zu schließen. Sie können den Schlüssel in der App „Einstellungen“ oder durch Eingabe von „TabletKeybind“ gefolgt von einem Schlüsselbuchstaben in der Entwicklerkonsole ändern.",
    ["ft_help_p1_open_title"] = "Öffnen des Tablets",
    ["ft_help_p1_title"] = "Öffnen und Navigieren",
    ["ft_help_p2_key_text"] = "Der Standardschlüssel ist T. Um ihn zu ändern, öffnen Sie die App „Einstellungen“ und suchen Sie die Einstellung „Tastenkombination“ oder geben Sie „TabletKeybind“ gefolgt von einem Schlüsselnamen in der Entwicklerkonsole ein – „TabletKeybind H“ setzt den Schlüssel beispielsweise auf „H“. Einzelbuchstaben, F-Tasten und allgemeine Tasten wie TAB und ESC werden alle unterstützt.",
    ["ft_help_p2_key_title"] = "Ändern des Öffnungsschlüssels",
    ["ft_help_p2_move_text"] = "Öffnen Sie die App „Einstellungen“ und klicken Sie auf „BEARBEITUNGSMODUS EINGEBEN“. Im Bearbeitungsmodus können Sie den Tablet-Körper ziehen, um ihn ein einer beliebigen Stelle auf dem Bildschirm neu zu positionieren, einen beliebigen Eckgriff ziehen, um das gesamte Tablet zu skalieren, oder den linken oder rechten Rund ziehen, um nur die Breite anzupassen. Klicken Sie mit der rechten Maustaste auf eine beliebige Stelle, um den Bearbeitungsmodus zu verlassen. Ihre Position und Ihr Maßstab werden automatisch gespeichert.",
    ["ft_help_p2_move_title"] = "Bearbeitungsmodus",
    ["ft_help_p2_title"] = "Verschieben und Größenänderung",
    ["ft_help_s1_settings_text"] = "Oeffne die Einstellungen-App, um das Tablet zu verwalten: Position und Groesse (oder Bearbeitungsmodus), Hintergrundfarbe, eigenes Startbild, den Sperrbildschirm, die Start-App, Toene und Benachrichtigungen. Alles wird automatisch gespeichert.",
    ["ft_help_s1_settings_title"] = "Was Sie ändern können",
    ["ft_help_s1_sound_text"] = "Soundeffekte sind standardmäßig aktiviert. Der App-Auswahlklick wird abgespielt, wenn Sie die App wechseln. Der Paging-Sound ertönt, wenn das Hilfefenster im Spiel geöffnet oder geschlossen wird. Beide können unabhängig voneinander in der Einstellungen-App umgeschaltet werden.",
    ["ft_help_s1_sound_title"] = "Soundeffekte",
    ["ft_help_s1_title"] = "Tablet-Einstellungen",
    ["ft_help_s2_console_text"] = "Oeffne die Entwicklerkonsole mit der Tilde-Taste und tippe tablet, um alle Befehle zu sehen. Beispiel: TabletKeybind H aendert die Oeffnen-Taste, TabletSetStartupApp weather setzt die Start-App, und TabletResetSettings stellt die Standardwerte wieder her.",
    ["ft_help_s2_console_title"] = "Verfügbare Befehle",
    ["ft_help_s2_title"] = "Konsolenbefehle",
    ["ft_lockscreen_date_day"] = "%s  -  Tag %d",
    ["ft_lockscreen_slide_to_unlock"] = "Zum Entsperren schieben",
