-- FarmTablet hard fallback German localization.
-- This is intentionally independent from GIANTS loading order so no visible UI
-- string falls back to English when the game is set to German.
local function ftIsGermanLanguage()
    local lang = ""
    if g_languageShort ~= nil then lang = tostring(g_languageShort) end
    if (lang == "" or lang == "nil") and g_i18n ~= nil then
        lang = tostring(g_i18n.languageShort or g_i18n.currentLanguage or g_i18n.language or "")
    end
    lang = string.lower(lang)
    return lang == "de" or lang == "ger" or lang == "deutsch" or lang:sub(1,2) == "de"
end

local _ftBaseL10n = FT.l10n
function FT.l10n(key, fallback)
    if g_i18n ~= nil and key ~= nil and g_i18n.hasText ~= nil and g_i18n:hasText(key) then
        local text = g_i18n:getText(key)
        if text ~= nil and text ~= "" and text ~= tostring(key) then return text end
    end
    if ftIsGermanLanguage() and FT.DE_L10N ~= nil and key ~= nil and FT.DE_L10N[tostring(key)] ~= nil then
        return FT.DE_L10N[tostring(key)]
    end
    return fallback or tostring(key or "")
end

local _ftBaseAuto = FT.l10nAuto
function FT.l10nAuto(text)
    local raw = tostring(text or "")
    if raw == "" then return raw end
    if not ftIsGermanLanguage() then
        return _ftBaseAuto ~= nil and _ftBaseAuto(raw) or raw
    end
    -- exact old map -> hard German table
    if FT.AUTO_L10N ~= nil then
        local key = FT.AUTO_L10N[raw]
        if key ~= nil and FT.DE_L10N ~= nil and FT.DE_L10N[key] ~= nil then return FT.DE_L10N[key] end
    end
    -- Farm-Admin composed strings from string.format calls
    local tm = raw:match("^TIME SCALE%s+[%·%-]+%s+now:%s*(.+)$") or raw:match("^TIME SCALE%s+.+now:%s*(.+)$")
    if tm then return "ZEITSKALIERUNG  ·  jetzt: " .. tm end
    local veh = raw:match("^VEHICLES%s+[%·%-]+%s+(%d+)%s+owned$")
    if veh then return "FAHRZEUGE  ·  " .. veh .. " im Besitz" end
    raw = raw:gsub("(%d+)%s+owned", "%1 im Besitz")
    raw = raw:gsub("TIME SCALE", "ZEITSKALIERUNG")
    raw = raw:gsub("SPRINGEN ZU", "SPRINGEN ZU")
    raw = raw:gsub("VEHICLES", "FAHRZEUGE")
    raw = raw:gsub("Vehicles", "Fahrzeuge")
    raw = raw:gsub("vehicles", "Fahrzeuge")
    raw = raw:gsub("now", "jetzt")
    raw = raw:gsub("owned", "im Besitz")
    raw = raw:gsub("6 AM", "6 UHR"):gsub("12 PM", "12 UHR"):gsub("6 PM", "18 UHR")
    raw = raw:gsub("MIDNIGHT", "MITTERNACHT"):gsub("Midnight", "Mitternacht")
    raw = raw:gsub("Autumn", "Herbst"):gsub("Spring", "Frühling"):gsub("Summer", "Sommer"):gsub("Winter", "Winter")
    local translated = _ftBaseAuto ~= nil and _ftBaseAuto(raw) or raw
    return translated
end


