}

local _ftPreviousAuto = FT.l10nAuto
function FT.l10nAuto(text)
    if text == nil then return "" end
    local raw = tostring(text)
    if raw == "" then return raw end
    if not ftRuntimeIsGerman() then
        return _ftPreviousAuto ~= nil and _ftPreviousAuto(raw) or raw
    end
    local map = FT.DE_RUNTIME_TEXT or {}
    if map[raw] ~= nil then return map[raw] end

    -- Common formatted strings and mixed German/English leftovers.
    raw = raw:gsub("(%d+)%s+total", "%1 gesamt")
    raw = raw:gsub("(%d+)%s+owned", "%1 im Besitz")
    raw = raw:gsub("(%d+)%s+vehicles", "%1 Fahrzeuge")
    raw = raw:gsub("(%d+)%s+Vehicles", "%1 Fahrzeuge")
    raw = raw:gsub("(%d+)%s+Fahrzeuge", "%1 Fahrzeuge")
    raw = raw:gsub("(%d+)%s+buildings", "%1 Gebäude")
    raw = raw:gsub("(%d+)%s+Gebäude", "%1 Gebäude")
    raw = raw:gsub("(%d+)%s+Silos", "%1 Silos")
    raw = raw:gsub("(%d+)%s+active", "%1 aktiv")
    raw = raw:gsub("(%d+)%s+pending", "%1 offen")
    raw = raw:gsub("(%d+)%s+done", "%1 erledigt")
    raw = raw:gsub("no active job", "kein aktiver Auftrag")
    raw = raw:gsub("no aktiv job", "kein aktiver Auftrag")
    raw = raw:gsub("none active", "keine aktiv")
    raw = raw:gsub("none aktiv", "keine aktiv")
    raw = raw:gsub("All done!", "Alles erledigt!")

    raw = raw:gsub("TIME SCALE", "ZEITSKALIERUNG")
    raw = raw:gsub("Time Scale", "Zeitskalierung")
    raw = raw:gsub("now", "jetzt")
    raw = raw:gsub("SKIP TO", "SPRINGEN ZU")
    raw = raw:gsub("FILL FUEL", "KRAFTSTOFF FÜLLEN")
    raw = raw:gsub("FILL KRAFTSTAUS", "KRAFTSTOFF FÜLLEN")
    raw = raw:gsub("ALL REPAIR", "ALLE REPARIEREN")
    raw = raw:gsub("6 AM", "6 UHR"):gsub("12 PM", "12 UHR"):gsub("6 PM", "18 UHR")
    raw = raw:gsub("MIDNIGHT", "MITTERNACHT"):gsub("Midnight", "Mitternacht")

    raw = raw:gsub("Farm Stats", "Hofstatistik"):gsub("Fleet Manager", "Flottenmanager"):gsub("Farm Admin", "Hof-Admin")
    raw = raw:gsub("Field Jobs", "Feldarbeiten"):gsub("Bucket Tracker", "Schaufelzähler"):gsub("Hotspot Manager", "Hotspot-Manager")
    raw = raw:gsub("Production", "Produktion"):gsub("Storage", "Lager"):gsub("Weather", "Wetter")

    raw = raw:gsub("FINANCES", "FINANZEN"):gsub("Finances", "Finanzen")
    raw = raw:gsub("Income", "Einnahmen"):gsub("Expenses", "Ausgaben"):gsub("Balance", "Kontostand")
    raw = raw:gsub("WORLD", "WELT"):gsub("World", "Welt"):gsub("Season", "Jahreszeit"):gsub("Day", "Tag")
    raw = raw:gsub("Autumn", "Herbst"):gsub("Spring", "Frühling"):gsub("Summer", "Sommer")
    raw = raw:gsub("Clear", "Klar"):gsub("CLEAR", "KLAR"):gsub("Warm", "Warm")
    raw = raw:gsub("CONDITIONS", "BEDINGUNGEN"):gsub("FORECAST", "VORHERSAGE")
    raw = raw:gsub("Temperature", "Temperatur"):gsub("Cloud Cover", "Bewölkung")
    raw = raw:gsub("INPUTS", "EINGÄNGE"):gsub("OUTPUTS", "AUSGÄNGE"):gsub("stalled", "steht")
    raw = raw:gsub("not installed", "nicht installiert"):gsub("OPEN", "ÖFFNEN")

    if map[raw] ~= nil then return map[raw] end
    local translated = _ftPreviousAuto ~= nil and _ftPreviousAuto(raw) or raw
    if map[translated] ~= nil then return map[translated] end
    return translated
end


-- =========================================================
-- FarmTablet Russian runtime localization sweep
-- Translates remaining legacy hardcoded app strings when the game language is Russian.
-- =========================================================
local function ftRuntimeIsRussian()
    local lang = ""
    if g_languageShort ~= nil then lang = tostring(g_languageShort) end
    if (lang == "" or lang == "nil") and g_i18n ~= nil then
        lang = tostring(g_i18n.languageShort or g_i18n.currentLanguage or g_i18n.language or "")
    end
    lang = string.lower(lang)
    return lang == "ru" or lang == "rus" or lang == "russian" or lang:sub(1,2) == "ru"
end

