local _ftRuPrevL10n = FT.l10n
function FT.l10n(key, fallback)
    local val = _ftRuPrevL10n ~= nil and _ftRuPrevL10n(key, fallback) or fallback
    if ftRuntimeIsRussian() and (val == nil or val == "" or val == tostring(key) or val == fallback) then
        if key ~= nil and FT.RU_L10N ~= nil and FT.RU_L10N[tostring(key)] ~= nil then
            return FT.RU_L10N[tostring(key)]
        end
    end
    return val
end

local _ftRuPrevAuto = FT.l10nAuto
function FT.l10nAuto(text)
    if text == nil then return "" end
    local raw = tostring(text)
    if raw == "" then return raw end
    if not ftRuntimeIsRussian() then
        return _ftRuPrevAuto ~= nil and _ftRuPrevAuto(raw) or raw
    end
    local map = FT.RU_RUNTIME_TEXT or {}
    if map[raw] ~= nil then return map[raw] end
    local prev = _ftRuPrevAuto ~= nil and _ftRuPrevAuto(raw) or raw
    if map[prev] ~= nil then return map[prev] end
    local out = prev
    -- common dynamic strings
    out = out:gsub("Autumn", "Осень"):gsub("Spring", "Весна"):gsub("Summer", "Лето"):gsub("Winter", "Зима")
    out = out:gsub("Day%s+(%d+)", "День %1")
    out = out:gsub("(%d+)%s+fields", "%1 поля"):gsub("(%d+)%s+vehicles", "%1 техники"):gsub("(%d+)%s+pens", "%1 загона"):gsub("(%d+)%s+silos", "%1 силосов")
    out = out:gsub("not installed", "не установлено"):gsub("installed", "установлено")
    out = out:gsub("OPEN", "ОТКРЫТЬ"):gsub("Ready", "Готово"):gsub("Closed", "Закрыто")
    out = out:gsub("KRAFTSTOFF", "ТОПЛИВО"):gsub("VERSCHLEISS", "ИЗНОС"):gsub("Std%.", "ч")
    out = out:gsub("FOOD", "КОРМ"):gsub("WATER", "ВОДА"):gsub("STRAW/CLEAN", "СОЛОМА/ЧИСТОТА")
    out = out:gsub("LOADS", "ЗАГРУЗКИ"):gsub("WEIGHT", "ВЕС"):gsub("ITEMS", "ПРЕДМЕТЫ")
    out = out:gsub("CONDITIONS", "УСЛОВИЯ"):gsub("FORECAST", "ПРОГНОЗ")
    if map[out] ~= nil then return map[out] end
    return out
end

-- =========================================================
-- FarmTablet RU final runtime localization sweep (v31)
-- Catches remaining hardcoded app strings which are still drawn through
-- renderer text/buttons instead of translation XML keys.
-- =========================================================
local function ft31IsRussianLanguage()
    local lang = ""
    if g_languageShort ~= nil then lang = tostring(g_languageShort) end
    if (lang == "" or lang == "nil") and g_i18n ~= nil then
        lang = tostring(g_i18n.languageShort or g_i18n.currentLanguage or g_i18n.language or "")
    end
    lang = string.lower(lang)
    return lang == "ru" or lang == "rus" or lang == "russian" or lang == "русский" or lang:sub(1,2) == "ru"
end

local function ft31PatEscape(s)
    return (tostring(s or ""):gsub("([%(%)%.%%%+%-%*%?%[%]%^%$])", "%%%1"))
end

