local _ft31PrevL10n = FT.l10n
function FT.l10n(key, fallback)
    if ft31IsRussianLanguage() then
        local k = tostring(key or "")
        if FT.RU_FINAL_TEXT ~= nil and FT.RU_FINAL_TEXT[k] ~= nil then return FT.RU_FINAL_TEXT[k] end
        if fallback ~= nil and FT.RU_FINAL_TEXT[tostring(fallback)] ~= nil then return FT.RU_FINAL_TEXT[tostring(fallback)] end
    end
    return _ft31PrevL10n ~= nil and _ft31PrevL10n(key, fallback) or (fallback or tostring(key or ""))
end

local _ft31PrevAuto = FT.l10nAuto
function FT.l10nAuto(text)
    if text == nil then return "" end
    local raw = tostring(text)
    if raw == "" then return raw end
    if not ft31IsRussianLanguage() then
        return _ft31PrevAuto ~= nil and _ft31PrevAuto(raw) or raw
    end
    local map = FT.RU_FINAL_TEXT or {}
    if map[raw] ~= nil then return map[raw] end
    local prev = _ft31PrevAuto ~= nil and _ft31PrevAuto(raw) or raw
    if map[prev] ~= nil then return map[prev] end
    local out = prev
    -- exact phrase replacements first
    local phrases = {
        ["Carport with power generation, numbering and lighting"]="Навес с генерацией, нумерацией и освещением",
        ["No invoices yet."]="Счетов пока нет.", ["Use + NEW to create your first invoice."]="Нажмите + НОВЫЙ, чтобы создать первый счет.",
        ["No jobs running."]="Работы не выполняются.", ["No completed jobs yet."]="Завершённых работ пока нет.",
        ["No todos yet — add one above"]="Дел пока нет — добавьте выше", ["No bucket vehicle detected nearby."]="Рядом не найден ковш/погрузчик.", ["No loads recorded yet."]="Загрузок пока нет.",
        ["Single station — no comparison available"]="Одна станция — сравнение недоступно", ["No sell price data found"]="Данных о ценах продажи нет", ["Silos are empty"]="Силосы пусты",
        ["Select a vehicle above to inspect."]="Выберите технику выше для осмотра.", ["Walk to scan terrain elevation"]="Подойдите для сканирования высоты рельефа",
        ["Accept contracts from NPCs on map."]="Принимайте контракты у NPC на карте.",
    }
    for a,b in pairs(phrases) do out = out:gsub(ft31PatEscape(a), b) end
    local words = {
        ["Dashboard"]="Панель управления", ["Weather"]="Погода", ["App Store"]="Магазин приложений", ["Settings"]="Настройки", ["Updates"]="Обновления",
        ["Field Manager"]="Полевой менеджер", ["Animals"]="Животные", ["Workshop"]="Мастерская", ["Digging"]="Копать", ["Bucket Tracker"]="Трекер ковша", ["Storage"]="Склад", ["Time Controls"]="Управление временем", ["Hotspot Manager"]="Метки карты", ["Notes"]="Заметки", ["Farm Admin"]="Админ фермы", ["Field Jobs"]="Полевые работы", ["Contracts"]="Контракты", ["Fleet Manager"]="Управление техникой", ["Production"]="Производство", ["Farm Stats"]="Статистика фермы", ["Invoices"]="Счета",
        ["CURRENT BALANCE"]="ТЕКУЩИЙ БАЛАНС", ["FINANCES"]="ФИНАНСЫ", ["SESSION P&L"]="П/У СЕССИИ", ["FARM TOTALS"]="ИТОГО ПО ФЕРМЕ", ["WORLD"]="МИР", ["FARM"]="ФЕРМА", ["CONDITIONS"]="УСЛОВИЯ", ["FORECAST"]="ПРОГНОЗ", ["INVENTORY"]="СКЛАД", ["BEST SELL PRICES"]="ЛУЧШИЕ ЦЕНЫ", ["PRICE COMPARISON"]="СРАВНЕНИЕ ЦЕН", ["ACTIVE VEHICLE"]="АКТИВНАЯ ТЕХНИКА", ["LOAD HISTORY"]="ИСТОРИЯ ЗАГРУЗОК", ["TERRAIN AT POSITION"]="РЕЛЬЕФ В ПОЗИЦИИ", ["TIME SCALE"]="МАСШТАБ ВРЕМЕНИ", ["SKIP TO"]="ПЕРЕЙТИ К", ["TODO LIST"]="СПИСОК ДЕЛ", ["NEW TODO"]="НОВАЯ ЗАДАЧА",
        ["Balance"]="Баланс", ["Net Worth"]="Состояние", ["Income"]="Доход", ["Expenses"]="Расходы", ["Net P/L"]="Чистая П/У", ["Fields"]="Поля", ["Area"]="Площадь", ["Vehicles"]="Техника", ["Animal Pens"]="Загоны животных", ["Season"]="Сезон", ["Day"]="День", ["Time"]="Время", ["Temperature"]="Температура", ["Cloud Cover"]="Облачность",
        ["INPUTS"]="ВХОДЫ", ["OUTPUTS"]="ВЫХОДЫ", ["LOADS"]="ЗАГРУЗКИ", ["WEIGHT"]="ВЕС", ["ITEMS"]="ПРЕДМЕТЫ", ["FOOD"]="КОРМ", ["WATER"]="ВОДА", ["STRAW/CLEAN"]="СОЛОМА/ЧИСТОТА", ["FUEL"]="ТОПЛИВО", ["WEAR"]="ИЗНОС", ["KRAFTSTOFF"]="ТОПЛИВО", ["VERSCHLEISS"]="ИЗНОС",
        ["Energy storage"]="Энергосклад", ["Fermenter small"]="Малый ферментер", ["Grass dryer"]="Сушилка травы", ["Sugar Beetchopper"]="Измельчитель свёклы", ["Sun energy"]="Солнечная энергия", ["Electric charge"]="Электрозаряд", ["Silage"]="Силос", ["Hay"]="Сено", ["Digestate"]="Дигестат", ["Stones"]="Камни", ["Sugarbeet cut"]="Резаная свёкла",
        ["Sheep"]="Овцы", ["Chicken"]="Куры", ["Pig"]="Свиньи", ["Cow"]="Коровы", ["WHEAT"]="ПШЕНИЦА", ["CANOLA"]="РАПС", ["MAIZE"]="КУКУРУЗА", ["GRASS"]="ТРАВА", ["Ready"]="Готово", ["READY"]="ГОТОВО", ["Closed"]="Закрыто", ["stalled"]="остановлено", ["installed"]="установлено", ["not installed"]="не установлено", ["OPEN"]="ОТКРЫТЬ", ["Open"]="Открыть", ["SELECT"]="ВЫБРАТЬ", ["RESET"]="СБРОС", ["PAUSE"]="ПАУЗА", ["MIDNIGHT"]="ПОЛНОЧЬ",
        ["Overall"]="Общее", ["Food"]="Корм", ["Water"]="Вода", ["Straw"]="Солома", ["Purchase Cost"]="Стоимость покупки", ["Care Cost"]="Стоимость ухода", ["Care Now"]="Ухаживать сейчас", ["LAST ACTION"]="ПОСЛЕДНЕЕ ДЕЙСТВИЕ",
        ["Saturday"]="Суббота", ["Sunday"]="Воскресенье", ["Monday"]="Понедельник", ["Tuesday"]="Вторник", ["Wednesday"]="Среда", ["Thursday"]="Четверг", ["Friday"]="Пятница", ["Autumn"]="Осень", ["Spring"]="Весна", ["Summer"]="Лето", ["Winter"]="Зима", ["Clear"]="Ясно", ["CLEAR"]="ЯСНО", ["Warm"]="Тепло",
    }
    local keys = {}
    for k,_ in pairs(words) do table.insert(keys, k) end
    table.sort(keys, function(a,b) return string.len(a) > string.len(b) end)
    for _,k in ipairs(keys) do out = out:gsub(ft31PatEscape(k), words[k]) end
    out = out:gsub("(%d+)%s+fields", "%1 поля"):gsub("(%d+)%s+vehicles", "%1 техники"):gsub("(%d+)%s+buildings", "%1 зданий"):gsub("(%d+)%s+pens", "%1 загона"):gsub("(%d+)%s+silos", "%1 силосов")
    out = out:gsub("Day%s+(%d+)", "День %1"):gsub("Day%s+%+(%d+)", "День +%1")
    out = out:gsub("(%d+)%s+owned", "%1 в собственности"):gsub("(%d+)%s+h", "%1 ч"):gsub("(%d+)%s+Std%.", "%1 ч")
    if map[out] ~= nil then return map[out] end
    return out
end

-- =========================================================
-- FarmTablet v2.5.2.1 - final visible text localization guard
-- Last safety layer for old apps that still send hardcoded labels directly
-- to the renderer. It is display-only, does not change gameplay/save data.
-- =========================================================
local function ft36LanguageShort()
    local lang = ""
    if g_languageShort ~= nil then lang = tostring(g_languageShort) end
    if (lang == "" or lang == "nil") and g_i18n ~= nil then
        lang = tostring(g_i18n.languageShort or g_i18n.currentLanguage or g_i18n.language or "")
    end
    lang = string.lower(lang)
    -- GIANTS sometimes uses full names/aliases in debug environments
    if lang:find("de", 1, true) == 1 or lang:find("ger", 1, true) == 1 then return "de" end
    if lang:find("ru", 1, true) == 1 or lang:find("rus", 1, true) == 1 then return "ru" end
    return lang
end

local function ft36EscapePattern(s)
    return tostring(s or ""):gsub("([%(%)%.%%%+%-%*%?%[%]%^%$])", "%%%1")
end

