local function ft36SmartTranslate(raw, lang)
    raw = tostring(raw or "")
    if raw == "" then return raw end
    local map = (lang == "de" and FT.FINAL_DE_TEXT) or (lang == "ru" and FT.FINAL_RU_TEXT) or nil
    if map == nil then return raw end
    if map[raw] ~= nil then return map[raw] end
    local out = raw
    local keys = {}
    for k,_ in pairs(map) do
        if type(k) == "string" and k ~= "" and string.len(k) > 1 then table.insert(keys, k) end
    end
    table.sort(keys, function(a,b) return string.len(a) > string.len(b) end)
    for _,k in ipairs(keys) do
        local v = map[k]
        if type(v) == "string" then out = out:gsub(ft36EscapePattern(k), v) end
    end
    if lang == "de" then
        out = out:gsub("Day%s+(%d+)", "Tag %1"):gsub("Day%s+%+(%d+)", "Tag +%1")
        out = out:gsub("(%d+)%s+fields", "%1 Felder"):gsub("(%d+)%s+vehicles", "%1 Fahrzeuge"):gsub("(%d+)%s+buildings", "%1 Gebäude"):gsub("(%d+)%s+pens", "%1 Ställe"):gsub("(%d+)%s+silos", "%1 Silos")
        out = out:gsub("(%d+)%s+owned", "%1 im Besitz"):gsub("(%d+)%s+h", "%1 Std.")
    elseif lang == "ru" then
        out = out:gsub("Day%s+(%d+)", "День %1"):gsub("Day%s+%+(%d+)", "День +%1")
        out = out:gsub("(%d+)%s+fields", "%1 поля"):gsub("(%d+)%s+vehicles", "%1 техники"):gsub("(%d+)%s+buildings", "%1 зданий"):gsub("(%d+)%s+pens", "%1 загона"):gsub("(%d+)%s+silos", "%1 силосов")
        out = out:gsub("(%d+)%s+owned", "%1 в собственности"):gsub("(%d+)%s+h", "%1 ч"):gsub("(%d+)%s+Std%.", "%1 ч")
    end
    return out
end

local _ft36PrevL10n = FT.l10n
function FT.l10n(key, fallback)
    local lang = ft36LanguageShort()
    if lang == "de" or lang == "ru" then
        local map = (lang == "de" and FT.FINAL_DE_TEXT) or FT.FINAL_RU_TEXT
        local k = tostring(key or "")
        if map[k] ~= nil then return map[k] end
        if fallback ~= nil then
            local fb = tostring(fallback)
            if map[fb] ~= nil then return map[fb] end
            local tr = ft36SmartTranslate(fb, lang)
            if tr ~= fb then return tr end
        end
    end
    return _ft36PrevL10n ~= nil and _ft36PrevL10n(key, fallback) or (fallback or tostring(key or ""))
end

local _ft36PrevAuto = FT.l10nAuto
function FT.l10nAuto(text)
    if text == nil then return "" end
    local raw = tostring(text)
    if raw == "" then return raw end
    local lang = ft36LanguageShort()
    local prev = _ft36PrevAuto ~= nil and _ft36PrevAuto(raw) or raw
    if lang == "de" or lang == "ru" then
        local direct = ft36SmartTranslate(raw, lang)
        if direct ~= raw then return direct end
        local afterPrev = ft36SmartTranslate(prev, lang)
        if afterPrev ~= prev then return afterPrev end
    end
    return prev
end

